import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s_input = scanner.nextLine();
        StringBuilder s_output = new StringBuilder();
        boolean at_used = false;
        int i = 0;
        while (i < s_input.length()) {
            if (i > 0 && i + 2 < s_input.length() && s_input.substring(i, i + 3).equals("dot")) {
                s_output.append('.');
                i += 3;
                continue;
            }
            if (!at_used && i > 0 && i + 1 < s_input.length() && s_input.substring(i, i + 2).equals("at")) {
                s_output.append('@');
                i += 2;
                at_used = true;
                continue;
            }
            s_output.append(s_input.charAt(i));
            i++;
        }
        System.out.println(s_output.toString());
    }
}
